Instance.ref.Members:
func GetTouchingElement(): GuiRawElementBase^ { return touching; }
prop TouchingElement: GuiRawElementBase^ {GetTouchingElement}

var centerX: double = 180.0;
var centerY: double = 140.0;
var axisX: double = 1.0;
var axisY: double = 0.0;
var markers: string = "";
var markerCount: int = 0;

func Publish(markers: string, count: int): void
{
  touching.Data = (cast string centerX) & "," & (cast string centerY)
    & "," & (cast string axisX) & "," & (cast string axisY)
    & "," & (cast string count) & markers;
}

func UpdatePoints(arguments: GuiPointEventArgs*): void
{
  markers = "";
  markerCount = 0;
  for (i in range[0, arguments.Points.Count))
  {
    if (var point: Point? = arguments.Points[i])
    {
      markers = markers & "," & (cast string i) & "," & (cast string point.x) & "," & (cast string point.y);
      markerCount = markerCount + 1;
    }
  }

  Publish(markers, markerCount);
}

Bounds.ev.pointGesture-eval:
{
              if (not arguments.handled and arguments.Gesture is GuiPointGesture_DraggingAndRotation)
              {
                var transform = cast GuiPointGesture_DraggingAndRotation arguments.Gesture;
                arguments.selected = true;
                arguments.handled = true;
                var real = transform.scale * Math::Cos(transform.rotation);
                var imaginary = transform.scale * Math::Sin(transform.rotation);
                var x = real * self.centerX - imaginary * self.centerY + cast double transform.distance.x;
                var y = imaginary * self.centerX + real * self.centerY + cast double transform.distance.y;
                var ax = real * self.axisX - imaginary * self.axisY;
                var ay = imaginary * self.axisX + real * self.axisY;
                self.centerX = x;
                self.centerY = y;
                self.axisX = ax;
                self.axisY = ay;
                self.Publish(self.markers, self.markerCount);
              }
            }
